"""Generate a self-contained static project page; publication copies site/ into GitHub Pages docs/."""
from pathlib import Path
import json,shutil,html
from PIL import Image
R=Path(__file__).resolve().parents[1];S=R/'site';A=S/'assets';A.mkdir(parents=True,exist_ok=True);C=json.loads((R/'config.json').read_text());PA=json.loads((R/'data/port-authority.json').read_text());credits={x['id']:x for x in json.loads((R/'data/photo-credits.json').read_text())};esc=lambda v:html.escape(str(v),quote=True)
for name in ['seeing-the-hudson.png','seeing-the-hudson-preview.png','05-thomas-hagos.png','pair-01.png','pair-02.png','pair-03.png','port-authority.png','port-authority-web.png']:shutil.copy2(R/'outputs'/name,A/name)
for p in C['pairs']:
 for side in ['nj','ny']:
  k=p[side]['photo'];shutil.copy2(R/'data/raw/photos'/(k+'.jpg'),A/(k+'.jpg'))
for src,name in [(R/'data/processed/viewpoints.csv','viewpoints.csv'),(R/'data/photo-credits.json','photo-credits.json'),(R/'README.md','methods.md'),(R/'data/processed/port-authority-crossings.csv','port-authority-crossings.csv'),(R/'docs/research-notes.md','research-notes.md'),(R/'data/port-authority.json','port-authority.json')]:shutil.copy2(src,A/name)
sections=[]
for p in C['pairs']:
 cards=[]
 for side in ['nj','ny']:
  s=p[side];r=credits[s['photo']];cards.append(f'''<figure class="photo"><img loading="lazy" src="assets/{r['id']}.jpg" alt="{esc(r['title'].removeprefix('File:') if hasattr(str,'removeprefix') else r['title'])}"><figcaption><span class="eyebrow">{side.upper()} / {esc(s['short'])}</span><h3>{esc(s['view'])}</h3><p>{esc(s['observation'])}</p><small>Photograph: <a href="{esc(r['page_url'])}">{esc(r['creator'])}</a> · {esc(r['capture_date'][:10])} · <a href="{esc(r['license_url'])}">{esc(r['license'])}</a>. Resized or cropped. Original photo linked above.</small><p class="site"><a href="{esc(s['source'])}">Official park information ↗</a></p></figcaption></figure>''')
 sections.append(f'''<section id="pair-{p['id']}"><div class="section-heading"><span class="index" style="color:{p['color']}">{p['id']}</span><div><span class="eyebrow">{esc(p['region'])}</span><h2>{esc(p['title'])}</h2></div></div><p class="section-intro">{esc(p['story'])}</p><p class="pa-link">{esc(PA['pair_links'][p['id']])}</p><div class="photo-grid">{''.join(cards)}</div><details><summary>Locate these two places</summary><a href="assets/pair-{p['id']}.png"><img class="pair-sheet" width="1280" height="1600" loading="lazy" src="assets/pair-{p['id']}.png" alt="North-up georeferenced aerial map and photographs of the {esc(p['title'])} site pairing"></a><p class="note">The line connects the two selected places; visibility between them has not been tested. Locations are approximate. Fort Lee uses the park entrance. Exact local capture dates for the USGS aerial imagery are unavailable.</p></details></section>''')

# Section 04: research-led refinement of the existing chapter.
rows=''.join(f'<li><b>{esc(v["year"])}</b><span>{esc(v["text"])} <a href="{esc(v["source"])}">Source</a>'+ (f' · <a href="{esc(v["secondary_source"])}">Further source</a>' if v.get('secondary_source') else '') +'</span></li>' for v in PA['facts'])
stats=''.join(f'<div><b>{v["count"]}</b><span>{esc(v["label"])}</span></div>' for v in PA['portfolio']['items'])
sections.append(f'''<section id="port-authority"><div class="section-heading"><span class="index" style="color:var(--gold)">04</span><div><span class="eyebrow">EMPIRE ON THE HUDSON</span><h2>{esc(PA['title'])}</h2></div></div>
<p class="section-intro">The river separates New York and New Jersey. In 1921, the two states created one agency to coordinate their shared port. <a href="{esc(PA['facts'][0]['source'])}">The Compact</a> made cooperation an institution.</p>
<figure class="pa-hero"><a href="assets/port-authority.png"><picture><source media="(max-width:700px)" srcset="assets/port-authority-web.png"><img loading="lazy" width="3500" height="3000" src="assets/port-authority.png" alt="Seeing the Hudson, section 04: 1921, Two states. One agency. The New York–New Jersey state line runs down the middle of the Hudson; five vermilion crossings, drawn in ink on paper, stitch across it, labelled 1908, 1909, 1927, 1931 and 1937."></picture></a><figcaption>One idea: the state line runs down the middle of the river, and the agency stitched across it. New Jersey and New York share one land colour; the dashed line is the state line. Crossings are schematic bank-to-bank links and anchors are approximate.</figcaption></figure>
<div class="actions"><a href="assets/port-authority.png">Landscape PNG</a><a href="assets/port-authority-web.png">Phone edition</a><a href="assets/port-authority-crossings.csv">Crossings CSV</a><a href="assets/research-notes.md">Research &amp; source checks</a></div>
<div class="pa-story"><p>Its works changed the scale of the region. The George Washington Bridge opened in 1931; Ammann’s main span was nearly twice the previous record. The agency leased LaGuardia and Idlewild/JFK in 1947, then Newark in 1948. <a href="https://blog.oup.com/2012/10/george-washington-bridge/">Bridge history</a> · <a href="https://corpinfo.panynj.gov/content/dam/corporate/consolidated-bonds-%26-notes-pdfs/port-authority-OS-series-227.pdf">Airport leases</a> · <a href="https://downloads.regulations.gov/FAA-2015-0026-0001/attachment_6.pdf">Newark lease</a>.</p>
<p>In 1956, Malcom McLean’s <em>Ideal X</em> sailed from Port Newark. Container shipping helped shift the port’s center of gravity toward New Jersey. The agency opened Elizabeth’s terminal in 1962—the year it also took over the H&amp;M railroad as PATH. The original World Trade Center followed in 1973. <a href="https://portfolio.panynj.gov/2015/06/23/the-world-in-a-box-a-quick-story-about-shipping/">Shipping</a> · <a href="https://www.panynj.gov/port/en/our-port/history.html">Elizabeth</a> · <a href="https://www.panynj.gov/path/en/about/history.html">PATH</a> · <a href="https://collection.911memorial.org/Detail/objects/121913">WTC dedication</a>.</p>
<p>That regional way of thinking also runs through the <a href="https://rpa.org/work/reports/the-constant-future">1929 Regional Plan</a> and Jean Gottmann’s <a href="https://www.press.jhu.edu/books/title/2357/megalopolis"><em>Megalopolis</em> (1961)</a>, the Boston–Washington urban chain with New York at its center. The Port Authority helped connect its New York–New Jersey core; it is one part of that larger story.</p>
<p class="note">Historical frame: Jameson W. Doig, <a href="https://cup.columbia.edu/book/empire-on-the-hudson/9780231076760/"><em>Empire on the Hudson</em> (2001)</a>. The map uses the stitch rather than a circle: the Compact defines the Port District through boundary points and connecting lines, not a literal 25-mile radius.</p></div>
<details class="pa-details"><summary>Dates, facilities and how to read the map</summary><div class="pa-grid"><div><h3>Selected milestones</h3><ol class="timeline">{rows}</ol><p class="note">The Holland Tunnel opened in 1927 and came under agency control in 1930. The Lincoln Tunnel opened in 1937, with more tubes in 1945 and 1957. H&amp;M’s river tubes predate PATH: 1908 and 1909. <a href="https://www.portauthoritybuilds.com/content/bridges-tunnels/en/holland-tunnel/history.html">Holland</a> · <a href="https://www.panynj.gov/bridges-tunnels/en/lincoln-tunnel/history.html">Lincoln</a> · <a href="https://www.panynj.gov/path/en/about/history.html">H&amp;M/PATH</a>.</p></div><div><h3>FY2026 portfolio</h3><div class="stats">{stats}</div><p class="note">Summary categories from the <a href="{esc(PA['portfolio']['source'])}">FY2026 budget, p. 4</a>, not counts of marks on this map. The agency has other responsibilities too.</p><p class="note">Solid line = bridge; dashes = road tunnel; dots = PATH river links. The airports, docks and WTC are part of the agency’s story told above but are left off the map to keep it on the river.</p><p class="note">Only the five Hudson crossings are mapped. Land and water: U.S. Census 2024 (1:500k counties minus TIGER/Line water); state line: TIGER/Line 2024. Anchors are approximate portal or terminal areas. Projection: NAD83 / UTM 18N; grid north; scale in miles. No surveyed alignment or legal jurisdiction boundary is drawn.</p><p class="note">IM FELL English roman and italic, Igino Marini (SIL OFL 1.1), supplies the lettering; DejaVu Sans carries the small print. Licenses and frozen source hashes are in the repository.</p></div></div></details></section>''')
h='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Two shores. One river. Different views. Six places to see the Hudson from its New York and New Jersey shores, and the Port Authority crossings that join them. A map by Thomas Hagos."><meta property="og:title" content="Seeing the Hudson — Thomas Hagos"><meta property="og:description" content="Two shores. One river. Different views."><meta property="og:image" content="https://flex-commits.github.io/30-days-mapping/seeing-the-hudson/assets/seeing-the-hudson-preview.png"><title>Seeing the Hudson — Thomas Hagos</title><style>
:root{color-scheme:dark;--bg:#101e2b;--fg:#f2eee2;--muted:#a8b7c2;--gold:#edb969;--line:#405562}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--fg);font:17px/1.65 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1160px;margin:auto;padding:44px 36px}a{color:var(--gold);text-underline-offset:4px}a:hover{color:var(--fg)}.top{display:flex;justify-content:space-between;gap:20px;font-size:12px;border-top:1px solid var(--gold);padding-top:18px}.eyebrow{font-size:11px;letter-spacing:.11em;color:var(--gold);font-weight:650;text-transform:uppercase}h1{font-size:clamp(48px,8vw,100px);line-height:1.02;letter-spacing:-.055em;margin:48px 0 20px;max-width:900px}h2{font-size:clamp(27px,4vw,43px);line-height:1.1;letter-spacing:-.03em;margin:8px 0}h3{font-size:20px;line-height:1.3;margin:12px 0}.subtitle{font-size:clamp(21px,3vw,31px);color:var(--muted);margin:0 0 24px}.intro{max-width:700px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:30px 0}.actions a{display:inline-block;border:1px solid var(--line);border-radius:2px;padding:10px 16px;text-decoration:none;font-size:13px}.actions a.primary{background:var(--gold);color:var(--bg);border-color:var(--gold);font-weight:650}.toc{display:flex;flex-wrap:wrap;gap:22px;font-size:13px;border-top:1px solid var(--line);padding-top:22px;margin-top:34px}img{max-width:100%;height:auto;display:block}.poster{margin:35px 0 0;background:#152633;padding:18px}.poster img{max-height:980px;width:auto;margin:auto}.poster figcaption{font-size:12px;color:var(--muted);max-width:800px;margin:18px auto 0}.note,small{color:var(--muted);font-size:12px;line-height:1.7}section{padding-top:65px;margin-top:35px;border-top:1px solid var(--line);scroll-margin-top:20px}.section-heading{display:flex;gap:20px;align-items:baseline}.index{font-size:45px;line-height:1;font-weight:700}.section-intro{max-width:700px;color:var(--muted)}.photo-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:30px 0}.photo{margin:0}.photo img{width:100%;height:280px;object-fit:cover;background:#172c39}.photo figcaption{padding:20px 0}.photo p{font-size:14px}.site a{font-size:12px}details{border:1px solid var(--line);padding:16px 20px}summary{cursor:pointer;font-size:14px;color:var(--gold)}.pair-sheet{width:100%;max-width:650px;margin:20px auto}.method-grid{display:grid;grid-template-columns:1fr 1fr;gap:35px}.method-grid p{font-size:14px;color:var(--muted)}.pa-hero{margin:30px 0}.pa-hero img{width:100%;height:auto}.pa-hero figcaption{font-size:12px;color:var(--muted);margin-top:14px;max-width:850px}.pa-story{max-width:800px}.pa-story p{font-size:16px}.pa-details{margin-top:28px}.pa-link{max-width:700px;font-size:14px;color:var(--fg);border-left:2px solid var(--gold);padding-left:14px}.pa-grid{display:grid;grid-template-columns:3fr 2fr;gap:40px;margin-top:30px}.timeline{list-style:none;padding:0;margin:0}.timeline li{display:grid;grid-template-columns:56px 1fr;gap:12px;padding:12px 0;border-top:1px solid var(--line);font-size:14px}.timeline b{font-size:17px}.timeline span{color:var(--muted)}.timeline strong{color:var(--fg)}.stats{display:grid;grid-template-columns:1fr 1fr;gap:18px 20px;margin:12px 0 18px}.stats b{display:block;font-size:38px;line-height:1}.stats span{font-size:13px;color:var(--muted)}footer{border-top:1px solid var(--line);margin-top:65px;padding:25px 0 10px;font-size:12px;color:var(--muted)}:focus-visible{outline:2px solid var(--gold);outline-offset:4px}@media(max-width:700px){main{padding:25px 20px}.pa-grid{grid-template-columns:1fr}.top{display:block}.top span{display:block;margin-top:7px}h1{margin-top:35px}.photo-grid,.method-grid{grid-template-columns:1fr}.photo img{height:auto}.poster{padding:5px}.index{font-size:32px}.section-heading{gap:14px}section{padding-top:35px}.toc{gap:15px}footer{margin-top:40px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style></head><body><main><header><div class="top"><a href="../">THOMAS HAGOS / 30-DAY MAP CHALLENGE</a><span>2026 · DAY 05 · SENSES: SIGHT</span></div><h1>Seeing<br>the Hudson.</h1><p class="subtitle">Two shores. One river. Different views.</p><p class="intro">Same river. Different picture.</p><p class="intro">I paired six public places on the New York and New Jersey shores. Two skylines, a sunset, a bridge… a different view from each side.</p><p class="intro">Then the links between them: the bridges, tunnels and trains the Port Authority built or took over to join the two shores.</p><div class="actions"><a class="primary" href="assets/seeing-the-hudson.png">Download the full map</a><a href="https://github.com/Flex-commits/30-days-mapping/tree/main/day05-seeing-hudson">Code & sources</a><a href="#reading">How to read it</a></div><nav aria-label="Site pairings" class="toc"><a href="#pair-01">01 / Skyline to skyline</a><a href="#pair-02">02 / A skyline. A sunset.</a><a href="#pair-03">03 / One bridge. Two frames.</a><a href="#port-authority">04 / One authority. Two shores.</a></nav></header><figure class="poster"><a href="assets/seeing-the-hudson.png"><img src="assets/seeing-the-hudson-preview.png" alt="Seeing the Hudson: an aerial map of six New York and New Jersey public sites with three pairs of credited historical waterfront photographs."></a><figcaption>Open the image for the full-size map. The dashed lines pair places for comparison. Open “Locate these two places” below each pair for a closer map.</figcaption></figure>__SECTIONS__<section id="reading"><span class="eyebrow">Sources & method</span><h2>Where the views come from.</h2><div class="method-grid"><div><h3>What the map shows</h3><p>The map marks six public places and pairs them across the river. Locations are approximate. Five come from the photographers’ coordinates; Fort Lee uses the park’s published entrance location. Maps face north and scales use miles. Projection: NAD83 / UTM zone 18N (EPSG:26918).</p><p>The dashed lines connect the places I chose to compare. I haven’t calculated what is visible between them or checked current access at every site.</p></div><div><h3>What the dates mean</h3><p>The aerial maps come from USDA/USGS. The service lists U.S. source imagery from 2017–2021 but does not give exact capture dates for these locations. Its June 2024 update date describes the service, not when the photos were taken. I darkened the map layer to keep labels readable; near-black pixels show the navy background.</p><p>These photos were taken between 2008 and 2022, on different days and in different conditions. Each one has its photographer, date, source and Creative Commons license listed beside it.</p></div></div><div class="actions"><a href="assets/viewpoints.csv">Viewpoint records CSV</a><a href="assets/photo-credits.json">Full photo credits</a><a href="https://github.com/Flex-commits/30-days-mapping/blob/main/day05-seeing-hudson/README.md">Complete methods</a></div></section><footer>Map and text: Thomas Hagos. Photographs by Dtabb73, Kidfly182, Famartin, G. Scott Segler, Jllm06 and Jmccabe371, via Wikimedia Commons (CC BY-SA 4.0; Jmccabe371 source CC BY-SA 3.0, as linked above). Composition: <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Poster, sheets and cards use resized/cropped photographic details; originals are linked. Aerial imagery: USDA / USGS / The National Map. DejaVu Sans. <br><br>#30DayMapChallenge · #teamMUSA · <a href="https://github.com/Flex-commits/30-days-mapping">Repository</a></footer></main></body></html>'''.replace('__SECTIONS__',''.join(sections))
(S/'index.html').write_text(h);print(S/'index.html')
